
UPDATE courses SET
    course_description = '<p><br/>Nursing is a career where your actions make a real, life-changing difference every day. Acknowledge Education’s Diploma of Nursing in Melbourne prepares you for exactly that, with a 18-month, ANMAC-accredited programme that combines clinical theory with 440 hours of real-world placement experience.</p> <p>This Diploma of Nursing covers everything from administering medicine and managing wounds to mental health care and aged care, training you to work as an enrolled nurse in hospitals, general practice, community health and aged care settings. You’ll also train in Acknowledge Education’s state-of-the-art simulated nursing laboratory using interactive mannequin technology before stepping onto the ward.</p> <p>Graduates are eligible to apply for registration with the Nursing and Midwifery Board of Australia as an enrolled nurse, with a direct pathway into the second year of a Bachelor of Nursing degree if you want to go further.</p>',
    total_course_duration = '',
    offshore_tuition_fee = '25200',
    entry_requirements = '<p>18 years or older</p> <p>Completed Year 12 or equivalent</p> <p>Confirmation of the month and year you commenced and complete these courses</p> <p>Confirmation of whether you were enrolled into these courses part time or full time</p> <p>Confirmation of whether you undertook these courses face-to-face or online</p> <p>Confirmation that these courses were taught in English</p> <p>IELTS Academic: Minimum overall score of 7 with a minimum score of 7 in listening, reading and speaking and 6.5 in writing</p> <p>OET: N/A</p> <p>PTE Academic: Minimum overall score of 63 with a core no less than 58 in listening, 59 in reading, 76 in speaking and 60 in writing</p> <p>TOEFL Internet based test (iBT): Minimum total score of 91 with a minimum score of 24 speaking, 23 in writing, and 22 in both listening and reading</p> <p>Cambridge C1 Advanced: Minimum overall score of 178 with no less than 175 in listening, 179 in reading, 194 in speaking and 180 in writing</p> <p>Cambridge C2 Proficiency: Minimum overall score of 185 with no less than 185 in listening, reading and speaking and 176 in writing</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/diploma-of-nursing-draft',
    updated_at = NOW()
WHERE cricos_course_code = '114531C';


UPDATE courses SET
    course_description = '<p>If your passion lies in the art of baking and crafting mouth-watering pastries, look no further than our esteemed Certificate III in Patisserie program. Designed to equip students with a comprehensive skill set and knowledge base, this course is a perfect choice for those aspiring to create delectable masterpieces in the world of patisserie.</p> <p>Throughout this program, you will dive deep into the intricate world of patisserie, honing your abilities to produce an array of delectable treats, including bread, cakes, pastries, and tarts. Under the guidance of our experienced instructors, you will master the techniques necessary to achieve impeccable flavours, textures, and presentations that will leave your customers in awe.</p> <p>Food safety and hygiene practices are paramount in the culinary industry, and this course ensures you are well-versed in these crucial matters. You will learn to prioritise cleanliness, organisation, and precision in your work, ensuring that the delectable creations you produce are not only visually stunning but also meet the highest standards of quality and safety.</p> <p>Our program is carefully crafted to provide a conducive learning environment, featuring state-of-the-art facilities and industry-standard equipment. You’ll have access to hands-on training and practical experiences that mirror the real-life challenges and expectations of the professional patisserie world.</p> <p>Join us on this delectable journey, where you will embrace your passion for pastry, refine your skills, and ignite your creativity. Don’t miss this opportunity to lay the foundation for a successful career in the culinary arts.</p>',
    total_course_duration = '',
    offshore_tuition_fee = '7800',
    entry_requirements = '<p>IELTS 5.5 or equivalent</p> <p>18 years or older</p> <p>Completion of Year 11 studies or equivalent</p> <p>Please see <a class="rich-text-link" href="https://ae.rtomanager.com.au/Publics/PublicsPages/DocView.aspx" rel="noreferrer" target="_blank">International Student Admission Policy and VET Assessment of Language, Literacy and Numeracy Skills Policy</a> for further information.</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/certificate-iii-in-patisserie',
    updated_at = NOW()
WHERE cricos_course_code = '109756F';


UPDATE courses SET
    course_description = '<p>Strong frontline leaders are in hot demand in hospitality across the globe. The Advanced Diploma of Hospitality Management will cultivate your passion for this vibrant industry and help you rise through the ranks to take your place as a Senior Manager. You’ll develop a thorough spectrum of skills across the areas of business planning, financial management, human resources, leadership and marketing, to enable you to successfully operate across a broad range of sectors which may include bars, gaming venues, resorts, restaurants or other busy hospitality environments.</p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
    entry_requirements = '<p>18 years or older</p> <p>Completion of Year 11 studies or equivalent</p> <p>IELTS 5.5 or equivalent</p> <p>Please see <a class="rich-text-link" href="https://ae.rtomanager.com.au/Publics/PublicsPages/DocView.aspx" rel="noreferrer" target="_blank">International Student Admissions (HE and VET) Policy</a> for further information.</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/advanced-diploma-of-hospitality-management',
    updated_at = NOW()
WHERE cricos_course_code = '110765F';


UPDATE courses SET
    course_description = '<p>If you’re a born leader, you’ll want to be front-of-house in your career, and the Diploma of Hospitality Management teaches you how to take charge in the fast-paced and exciting world of hospitality. You’ll acquire a broad range of hospitality skills, including providing food and beverage advice and table service, combined with managerial skills such as managing staff performance and preparing and monitoring budgets. You’ll gain a sound knowledge of the industry in order to coordinate hospitality operations and take on the role of a highly skilled senior employee capable of making operational business decisions.</p> <p>This qualification provides a pathway to work in any hospitality industry sector as a departmental or business manager. The range of employers includes cafes, catering companies, clubs, hotels, motels, pubs and restaurants, among others. This qualification allows for multiskilling and for specialisation in accommodation services, cookery, food and beverage, and gaming.</p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
    entry_requirements = '<p>Entry by interview</p> <p>You may be able to shorten your chosen course by factoring in skills acquired through work, life experiences or qualifications obtained from prior formal studies or training. Acknowledge Education recognises AQF qualifications and statements of attainment issued by other registered training organisations.</p> <p>Please see <a class="rich-text-link" href="http://www.frontcookingschool.vic.edu.au/wp-content/uploads/sites/4/2019/02/POLICY-AND-PROCEDURE-VET-Recognition-of-Prior-Learning-and-Credit-Transfer-180605-Copy.pdf" rel="noreferrer" target="_blank">Recognition of Prior Learning and Credit Transfer</a> for more information.</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/diploma-of-hospitality-management',
    updated_at = NOW()
WHERE cricos_course_code = '110764G';


