UPDATE courses SET
    course_description = '<p>Kick start your career in the civil construction industry with the Diploma of Civil Construction Design. This qualification prepares you for work as a designer or design paraprofessional who supports professional engineers. The course prepares you to perform tasks involving a high level of autonomy and requiring significant judgement in planning and selecting equipment, roles and techniques. <br/> <br/>You will develop site-specific work designs to support the implementation of clients’ site requirements. You will also learn to use 2D and 3D industry software applications, including Building Information Modelling (BIM) tools, which are essential for designing construction and infrastructure projects. </p>',
    total_course_duration = '',
    offshore_tuition_fee = '15000',
