UPDATE courses SET
    course_description = '<p>The International English Language Testing System (IELTS) is the fastest growing English test in the world and is widely accepted for enrolment into higher education institutions internationally (please visit <a class="rich-text-link" href="https://www.ielts.org/" rel="noreferrer" target="_blank"><b>https://www.ielts.org/</b></a> for more details).</p> <p>The IELTS Preparation course at Acknowledge Education is ideal for students wishing to improve their IELTS score in either the General or Academic modules. The course will fully prepare you for the test.</p> <p>You will:</p> <p>• Be familiarised with the nature and format of the exam</p> <p>• Be provided with numerous practice tests</p> <p>• Receive advice and strategies regarding the exam</p> <p>• Improve your overall language skills within the IELTS context</p> <p>• Be assessed with listening, reading, speaking and writing tests to assist you in your learning</p> <p>Universities and educational institutions normally require an overall IELTS band score of between 6.0 and 7.5. If you are interested in studying in Australia or New Zealand, this test is essential.</p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
    entry_requirements = '<p>Minimum 18 years old.</p> <p>A consistent IELTS band score of 5.5 is recommended as a minimum entry requirement for this course.</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/ielts-preparation',
    updated_at = NOW()
WHERE cricos_course_code = '080629M';


UPDATE courses SET
    course_description = '<p>With almost forty years of experience in teaching young students, Acknowledge Education (formally known as Melbourne Language Centre) is recognised as a leader in providing tailored English preparation courses in Victoria, catering to high school students.</p> <p>The curriculum recognises the dual need for students to develop their general English language skills while also preparing them for future study in Australian high schools.</p> <p>Morning classes prioritise English language and communication, with students grouped based on their English proficiency as determined through rigorous testing during orientation. Throughout the day, significant time is dedicated to exploring daily concepts within the English language in both classroom and educative settings, preparing students for their pathway schools. Students continue to delve into academic language relevant to the Australian curriculum in the afternoon, maintaining groupings based on their English proficiency levels. As students advance in their language learning, they will have opportunities to apply their new skills during monthly excursions around the city. </p> <p>Specialist teachers are employed to teach mathematics and science, with students introduced to the concepts they can expect to study at their future schools. Homework is an integral part of the student program and is monitored by the classroom teacher on a daily basis. Excursions are organised regularly and include a range of cultural and social activities such as visits to museums, sightseeing tours, day hikes, sports days, and barbecues.</p> <p>The course is underpinned by:</p> <p>Content and Language Integrated Learning (CLIL), including maths, science, literature, history, geography, art and PE</p> <p>Aspects of Victorian Curriculum Foundation–10 for EAL</p> <p>Effective use of educational technology for both individual and group activities</p> <p>Regular cultural/social activities and excursions</p> <p>Excellence in teaching practice for all macro skills (reading, writing, listening and speaking) and enabling skills (pronunciation, spelling, vocabulary, grammar and punctuation)</p> <p>Regular liaison with a broad network of both independent and government pathway schools</p> <p><b>Teaching</b></p> <p>The teaching and assessment methods at Acknowledge Education include:</p> <p>Traditional classroom delivery</p> <p>Online support materials</p> <p>Consideration of different learning styles, abilities and preferences</p> <p>Group work and pair work, as well as individual assignments</p> <p>Interactive educational games and activities</p> <p>Regular formal and informal assessments and reports/feedback</p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
    entry_requirements = '',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/english-for-secondary-schools',
    updated_at = NOW()
WHERE cricos_course_code = '080627B';


UPDATE courses SET
    course_description = '<p>The Victorian Certificate of Education (VCE) is Victoria’s senior secondary qualification and a powerful pathway to your future. Recognised nationally and internationally, the VCE opens doors to university study, vocational education and training (VET), and direct entry into the workforce.</p> <p>At Acknowledge Education, we offer more than just a qualification — we provide a supportive, student-centred learning experience designed to help you achieve your best. Our dedicated teachers work closely with students, creating an environment where questions are encouraged, confidence is built, and academic success is supported every step of the way.</p> <p>When you study VCE with us, you benefit from:</p> <p>Experienced and supportive teachers</p> <p>Personalised academic guidance</p> <p>Close-knit, inclusive learning community</p> <p>Focus on your goals and future pathways</p> <p>Whether your ambition is university, further training, or employment, the VCE at Acknowledge Education equips you with the knowledge, skills, and confidence to move forward with clarity and success.</p>',
    total_course_duration = '',
    offshore_tuition_fee = '19000',
    entry_requirements = '<p><b>Year 11</b></p> <p>• Completion of year 10<br/>• IELTS 5.5 or equivalent*<br/>• <!-- -->If you need to improve your English, you can complete our <a class="rich-text-link" href="https://www.acknowledgeeducation.edu.au/courses/english-for-secondary-schools" rel="noreferrer" target="_blank"><b>English for Secondary Schools</b></a> program before starting Year 11. This course supports your transition into VCE by building essential language and study skills. <!-- -->`</p> <p><b>Year 12</b></p> <p>• Completion of year 11</p> <p><b>Year 11</b></p> <p>• Completion of year 10<br/>• IELTS 5.5 or equivalent*<br/>• <!-- -->If you need to improve your English, you can complete our <a class="rich-text-link" href="https://www.acknowledgeeducation.edu.au/courses/english-for-secondary-schools" rel="noreferrer" target="_blank"><b>English for Secondary Schools</b></a> program before starting Year 11. This course supports your transition into VCE by building essential language and study skills. <!-- -->`</p> <p><b>Year 12</b></p> <p>• Completion of year 11<br/>• IELTS 5.5 or equivalent</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/vce-year-11-12',
    updated_at = NOW()
WHERE cricos_course_code = '032533F';


UPDATE courses SET
    course_description = '<p>English for Academic Purposes is designed to prepare you for your continuing tertiary education, at Certificate, Diploma, Undergraduate and Postgraduate levels.</p> <p>You are taught English language skills that will enable you to succeed in an academic environment. Presentation skills, essay writing, and comprehensive listening tasks all give you the best advantage when you go on to study at an Australian university. You are also exposed to advanced grammar and language skills</p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
    entry_requirements = '<p>Minimum 18 years old.</p> <p>A consistent IELTS band of 5.5 is recommended as a minimum entry requirement for this course.</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/english-for-academic-purposes',
    updated_at = NOW()
WHERE cricos_course_code = '080625D';


UPDATE courses SET
    course_description = '<p>At Acknowledge Education, you’ll study General English in a fun, relaxed and multicultural environment. Quickly pick up basic language skills to help you settle into life in Australia and deal with everyday situations with ease.The General English course focuses on communication skills within a variety of functional and situational contexts and improves your language skills (Reading, Writing, Listening and Speaking) in real life situations such as working, studying, travelling or living in Australia.</p> <p>We will support you during your English studies by:</p> <p>Offering extra-curricular classes including conversation club and social trips, focusing on speaking skill and cultural/social features of living in Australia</p> <p>Providing support sessions with an individual learning plan, focusing on all language skills including Reading, Writing, Listening, Speaking, Grammar, Vocabulary, Pronunciation and Punctuation</p> <p>Running academic and language skills development workshops</p> <p>Giving you access to online learning materials</p> <p>Arranging meetings with academic advisors, student support officers, and program coordinators</p> <p>General English is offered at Elementary, Pre-intermediate, Intermediate and Upper-intermediate levels and can serve as the perfect stepping stone to the study of English for Academic Purposes and IELTS courses.</p>',
    total_course_duration = '',
    offshore_tuition_fee = '',
    entry_requirements = '<p>Minimum 18 years old.</p>',
    apply_form = 'https://www.acknowledgeeducation.edu.au/courses/general-english',
    updated_at = NOW()
WHERE cricos_course_code = '080628A';
